/**
 * Pure logic operations for bitwise arrays.
 * Decouples the mathematical logic from the circuit state management.
 */

// Utility: Apply binary operation bit-by-bit
export const bitwiseOp = (
  a: boolean[], 
  b: boolean[] | null, 
  op: (x: boolean, y: boolean) => boolean
): boolean[] => {
    const len = a.length;
    // Safe fallback if b is missing or shorter
    const safeB = b || new Array(len).fill(false);

    const res = new Array(len);
    for(let i = 0; i < len; i++) {
        // Handle mismatched lengths by treating missing bits as false (0)
        const valB = i < safeB.length ? safeB[i] : false;
        res[i] = op(a[i], valB);
    }
    return res;
};

export const bitwiseNot = (a: boolean[]): boolean[] => a.map(v => !v);

export const gateNot = (input: boolean[]) => bitwiseNot(input);
export const gateAnd = (a: boolean[], b: boolean[]) => bitwiseOp(a, b, (x, y) => x && y);
export const gateOr = (a: boolean[], b: boolean[]) => bitwiseOp(a, b, (x, y) => x || y);
export const gateNand = (a: boolean[], b: boolean[]) => bitwiseNot(gateAnd(a, b));
export const gateNor = (a: boolean[], b: boolean[]) => bitwiseNot(gateOr(a, b));
export const gateXor = (a: boolean[], b: boolean[]) => bitwiseOp(a, b, (x, y) => x !== y);

export const splitBus = (input: boolean[], width: number): [boolean[], boolean[]] => {
    const half = Math.floor(width / 2);
    // Safety check
    if (input.length < width) {
        // Pad input if shorter than expected width
        const padded = [...input, ...new Array(width - input.length).fill(false)];
        return [padded.slice(0, half), padded.slice(half)];
    }
    return [input.slice(0, half), input.slice(half)];
};

export const mergeBus = (low: boolean[], high: boolean[], targetWidth: number): boolean[] => {
    const half = Math.floor(targetWidth / 2);
    // Pad or trim inputs to ensure they fit the half-width
    const safeLow = low.length === half ? low : [...low, ...new Array(Math.max(0, half - low.length)).fill(false)].slice(0, half);
    const safeHigh = high.length === half ? high : [...high, ...new Array(Math.max(0, half - high.length)).fill(false)].slice(0, half);
    return [...safeLow, ...safeHigh];
};

import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import * as GateLogic from './gateLogic';

/**
 * Logic Engine - Supports Multi-bit Bus Processing
 * Refactored for SOLID principles: Logic calculations delegated to GateLogic.
 */

// Helper: Ensure input array exists and has correct width
const safeInput = (inputs: boolean[][], idx: number, width: number): boolean[] => {
    if (!inputs[idx]) return new Array(width).fill(false);
    if (inputs[idx].length === width) return inputs[idx];

    // Resize/Pad if mismatch
    const current = inputs[idx];
    if (current.length < width) {
        return [...current, ...new Array(width - current.length).fill(false)];
    }
    return current.slice(0, width);
};

const evaluateComponent = (comp: CircuitComponent, inputs: boolean[][], currentOutputs: boolean[][]): boolean[][] => {
  const width = comp.bitWidth;

  switch (comp.type) {
    case ComponentType.INPUT_SWITCH:
      // State is maintained in outputValues[0] by the UI/Interaction layer.
      // We just ensure robustness here.
      if (!currentOutputs[0] || currentOutputs[0].length !== width) {
           // Preserve existing values if resizing, or default to false
           const old = currentOutputs[0] || [];
           const newArr = new Array(width).fill(false);
           for(let i=0; i<Math.min(old.length, width); i++) newArr[i] = old[i];
           return [newArr];
      }
      return currentOutputs;

    case ComponentType.OUTPUT_LED:
    case ComponentType.HEX_DISPLAY:
      return []; // Passive components have no logical output to propagate

    case ComponentType.NOT:
      return [GateLogic.gateNot(safeInput(inputs, 0, width))];

    case ComponentType.AND:
      return [GateLogic.gateAnd(safeInput(inputs, 0, width), safeInput(inputs, 1, width))];

    case ComponentType.OR:
      return [GateLogic.gateOr(safeInput(inputs, 0, width), safeInput(inputs, 1, width))];

    case ComponentType.NAND:
      return [GateLogic.gateNand(safeInput(inputs, 0, width), safeInput(inputs, 1, width))];

    case ComponentType.NOR:
      return [GateLogic.gateNor(safeInput(inputs, 0, width), safeInput(inputs, 1, width))];

    case ComponentType.XOR:
      return [GateLogic.gateXor(safeInput(inputs, 0, width), safeInput(inputs, 1, width))];

    case ComponentType.SPLITTER: {
        if (width < 2) return [safeInput(inputs, 0, width), safeInput(inputs, 0, width)];
        const [low, high] = GateLogic.splitBus(safeInput(inputs, 0, width), width);
        return [low, high];
    }

    case ComponentType.MERGER: {
        if (width < 2) return [safeInput(inputs, 0, width)]; 
        const half = Math.floor(width / 2);
        const merged = GateLogic.mergeBus(
            safeInput(inputs, 0, half), 
            safeInput(inputs, 1, half), 
            width
        );
        return [merged];
    }

    default:
      return currentOutputs;
  }
};

// Helper: Port Ordering for ICs
const getSide = (c: CircuitComponent, isInput: boolean): PortSide => {
    return c.icPortSide || (isInput ? 'left' : 'right');
};

const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

const sortComponents = (components: CircuitComponent[], isInput: boolean) => {
    return [...components].sort((a, b) => {
        const sideA = getSide(a, isInput);
        const sideB = getSide(b, isInput);

        if (sideOrder[sideA] !== sideOrder[sideB]) {
            return sideOrder[sideA] - sideOrder[sideB];
        }
        if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
        return a.y - b.y;
    });
};

export const stepSimulation = (
  currentComponents: CircuitComponent[],
  wires: Wire[],
  functionLibrary: FunctionCircuit[] = []
): { components: CircuitComponent[], wires: Wire[] } => {

  // 1. Double Buffering: Clone state to avoid mutation during read
  const nextComponents = currentComponents.map(c => ({
    ...c,
    inputValues: c.inputValues.map(arr => [...arr]),
    outputValues: c.outputValues.map(arr => [...arr]),
    internalState: c.internalState ? {
        components: [...c.internalState.components],
        wires: [...c.internalState.wires]
    } : undefined
  }));

  const prevCompMap = new Map(currentComponents.map(c => [c.id, c]));
  const nextCompMap = new Map(nextComponents.map(c => [c.id, c]));

  // 2. Clear Inputs for the next tick
  for (const comp of nextComponents) {
     comp.inputValues = []; 
  }

  // 3. Propagate Wires (Data Transfer)
  for (const wire of wires) {
    const sourceComp = prevCompMap.get(wire.fromCompId);
    const destComp = nextCompMap.get(wire.toCompId);

    if (sourceComp && destComp) {
      // Robustness: Handle missing outputs gracefully
      const sourceBus = sourceComp.outputValues[wire.fromPortIndex] || new Array(wire.bitWidth).fill(false);

      if (!destComp.inputValues[wire.toPortIndex]) {
          destComp.inputValues[wire.toPortIndex] = [...sourceBus];
      } else {
          // Bus contention logic: Bitwise OR
          const existing = destComp.inputValues[wire.toPortIndex];
          const combinedLen = Math.max(existing.length, sourceBus.length);
          const combined = new Array(combinedLen);
          for(let i=0; i<combinedLen; i++) {
              combined[i] = (existing[i] || false) || (sourceBus[i] || false);
          }
          destComp.inputValues[wire.toPortIndex] = combined;
      }
    }
  }

  // 4. Compute Logic for each component
  for (const comp of nextComponents) {
    // Input Switches don't calculate based on inputs, they hold user state
    if (comp.type === ComponentType.INPUT_SWITCH) continue;

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId && comp.internalState) {
        // --- CUSTOM IC RECURSION ---
        const funcDef = functionLibrary.find(f => f.id === comp.functionId);

        if (funcDef) {
            const inputsDef = sortComponents(
                funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH),
                true
            );
            const outputsDef = sortComponents(
                funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED),
                false
            );

            const internalState = comp.internalState;

            // Map External Inputs -> Internal Switches
            inputsDef.forEach((def, index) => {
                const internalSwitch = internalState.components.find(c => c.id === def.id);
                if (internalSwitch) {
                    const val = comp.inputValues[index] || new Array(comp.bitWidth).fill(false);
                    internalSwitch.outputValues = [val]; 
                    // Dynamically update internal width to match external drive
                    internalSwitch.bitWidth = val.length; 
                }
            });

            // Step Internal Circuit
            const result = stepSimulation(internalState.components, internalState.wires, functionLibrary);
            comp.internalState = result;

            // Map Internal LEDs -> External Outputs
            const newOutputs: boolean[][] = [];
            outputsDef.forEach((def) => {
                const internalLed = result.components.find(c => c.id === def.id);
                if (internalLed && internalLed.inputValues[0]) {
                    newOutputs.push(internalLed.inputValues[0]);
                } else {
                    newOutputs.push(new Array(comp.bitWidth).fill(false)); 
                }
            });
            comp.outputValues = newOutputs;
        }
    } else {
        // Standard Component Logic
        comp.outputValues = evaluateComponent(comp, comp.inputValues, comp.outputValues);
    }
  }

  // 5. Update Wire Visual States for rendering
  const nextWires = wires.map(w => {
    const sourceComp = nextCompMap.get(w.fromCompId);
    let val: boolean[] = new Array(w.bitWidth).fill(false);
    if (sourceComp && sourceComp.outputValues[w.fromPortIndex]) {
        val = sourceComp.outputValues[w.fromPortIndex];
    }
    return { ...w, state: val };
  });

  return { components: nextComponents, wires: nextWires };
};

import React, { useRef } from 'react';
import { ComponentType } from '../types';

interface DraggableItemProps {
    type: ComponentType;
    label: string;
    subLabel: string;
    disabled: boolean;
    bitWidth: number;
    functionId?: string;
    isCustom?: boolean;
    onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
}

const useLongPressDrag = (
    disabled: boolean, 
    callback: (pos: {x: number, y: number}) => void
) => {
    const timerRef = useRef<number>(0);

    const onTouchStart = (e: React.TouchEvent) => {
        if (disabled) return;
        const touch = e.touches[0];
        const pos = { x: touch.clientX, y: touch.clientY };

        // Short delay to differentiate tap/scroll from drag init
        timerRef.current = window.setTimeout(() => {
             if (navigator.vibrate) navigator.vibrate(40);
             callback(pos);
        }, 250); 
    };

    const clear = () => {
        if (timerRef.current) {
            clearTimeout(timerRef.current);
            timerRef.current = 0;
        }
    };

    return {
        onTouchStart,
        onTouchEnd: clear,
        onTouchMove: clear,
        onContextMenu: (e: React.MouseEvent) => { if (!disabled) e.preventDefault(); }
    };
};

const DraggableItem: React.FC<DraggableItemProps> = ({ 
    type, label, subLabel, disabled, bitWidth, functionId, isCustom, onTouchStartItem 
}) => {

    const handleDragStart = (e: React.DragEvent) => {
        if (disabled) return;
        e.dataTransfer.setData('application/react-logic-sim', JSON.stringify({ type, functionId, bitWidth }));
        e.dataTransfer.effectAllowed = 'copy';
    };

    const touchHandlers = useLongPressDrag(disabled, (pos) => {
        if (onTouchStartItem) onTouchStartItem(type, pos, functionId);
    });

    if (isCustom) {
        return (
             <div
                draggable={!disabled}
                onDragStart={handleDragStart}
                {...touchHandlers}
                className="flex items-center p-2 rounded border border-slate-200 bg-blue-50 hover:border-blue-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing select-none"
            >
                 <div className="w-6 h-6 mr-3 border border-blue-200 rounded flex items-center justify-center bg-white text-[9px] font-bold text-blue-600 pointer-events-none">
                    IC
                 </div>
                 <span className="text-sm font-medium text-slate-700 pointer-events-none truncate">{label}</span>
            </div>
        );
    }

    return (
        <div
            draggable={!disabled}
            onDragStart={handleDragStart}
            {...touchHandlers}
            className={`flex flex-col items-center justify-center p-3 rounded border-2 transition-all duration-200 select-none
                ${disabled 
                    ? 'opacity-40 bg-slate-50 border-slate-100 cursor-not-allowed' 
                    : 'bg-white border-slate-100 hover:border-slate-300 hover:shadow-sm cursor-grab active:cursor-grabbing'}`}
        >
            <div className="w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-white text-[10px] font-bold text-slate-600 pointer-events-none">
                {label.substring(0,3)}
            </div>
            <span className="text-xs font-medium text-slate-700 pointer-events-none">{label}</span>
            <span className="text-[9px] text-slate-400 font-mono mt-1">{subLabel}</span>
        </div>
    );
};

export default DraggableItem;

import React from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS, VALID_BIT_WIDTHS } from '../constants';
import DraggableItem from './DraggableItem';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  selectedBitWidth: number;
  onSelectBitWidth: (w: number) => void;
  onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
}

const Sidebar: React.FC<SidebarProps> = ({ 
    selectedTool, 
    onSelectTool, 
    selectedBitWidth, 
    onSelectBitWidth,
    onTouchStartItem, 
    functionLibrary 
}) => {
  const groups = [
    { name: 'Bus Tools', items: [ComponentType.SPLITTER, ComponentType.MERGER] },
    { name: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] }
  ];

  const draggableFunctions = functionLibrary.filter(f => f.id !== 'main');

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100 bg-slate-50/50">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Bus Width Simulator</p>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 overscroll-contain scrollbar-thin">

        {/* Tools Section */}
        <section>
          <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">Tools</h3>
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`p-2 rounded text-sm font-medium transition-colors flex items-center justify-center gap-2 ${selectedTool === 'SELECT' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              <span>👆</span> Select
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-sm font-medium transition-colors flex items-center justify-center gap-2 ${selectedTool === 'DELETE' ? 'bg-red-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              <span>🗑️</span> Delete
            </button>
          </div>
        </section>

        {/* Bit Width Section */}
        <section>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 pl-1">Bus Width (Bits)</h3>
            <div className="flex flex-wrap gap-1.5">
                {VALID_BIT_WIDTHS.map(w => (
                    <button
                        key={w}
                        onClick={() => onSelectBitWidth(w)}
                        className={`px-2.5 py-1 text-xs font-bold rounded border transition-all ${selectedBitWidth === w 
                            ? 'bg-blue-100 border-blue-400 text-blue-700 shadow-sm scale-105' 
                            : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                    >
                        {w}
                    </button>
                ))}
            </div>
        </section>

        {/* Component Groups */}
        {groups.map(group => (
          <section key={group.name}>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                const disabled = (type === ComponentType.SPLITTER || type === ComponentType.MERGER) && selectedBitWidth < 2;
                const subLabel = type === ComponentType.SPLITTER ? `${selectedBitWidth}→${selectedBitWidth/2}` : 
                                 type === ComponentType.MERGER ? `${selectedBitWidth/2}→${selectedBitWidth}` : 
                                 `x${selectedBitWidth}`;

                return (
                   <DraggableItem 
                        key={type}
                        type={type}
                        label={def.label}
                        subLabel={subLabel}
                        disabled={disabled}
                        bitWidth={selectedBitWidth}
                        onTouchStartItem={onTouchStartItem}
                   />
                );
              })}
            </div>
          </section>
        ))}

        {/* Custom Functions Section */}
        {draggableFunctions.length > 0 && (
            <section>
                 <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">My Functions</h3>
                 <div className="grid grid-cols-1 gap-2">
                    {draggableFunctions.map(func => (
                        <DraggableItem
                            key={func.id}
                            type={ComponentType.CUSTOM_IC}
                            label={func.name}
                            subLabel=""
                            disabled={false}
                            bitWidth={selectedBitWidth}
                            functionId={func.id}
                            isCustom={true}
                            onTouchStartItem={onTouchStartItem}
                        />
                    ))}
                 </div>
            </section>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

