                               value={tempLabel}
                               onChange={(e) => onLabelChange(e.target.value)}
                               className="bg-transparent text-sm text-slate-800 px-1 py-0.5 w-20 focus:outline-none placeholder-yellow-300/50"
                               placeholder="Label"
                           />
                        </div>
                    </div>
                )}

                <div className="relative">
                    <button 
                        onClick={() => setIsProjectMenuOpen(!isProjectMenuOpen)} 
                        className={`px-3 py-2 border rounded-md text-sm font-semibold transition-colors flex items-center gap-2
                        ${isProjectMenuOpen ? 'bg-slate-100 border-slate-300 text-slate-800' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                    >
                        <span>Menu</span>
                        <span className="text-[10px]">▼</span>
                    </button>
                    {isProjectMenuOpen && (
                        <>
                            <div className="fixed inset-0 z-40" onClick={() => setIsProjectMenuOpen(false)}></div>
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white rounded-lg shadow-xl border border-slate-100 py-2 z-50 flex flex-col animate-scale-in origin-top-right">
                                <div className="px-4 py-2 text-[10px] font-mono text-slate-400 border-b mb-1 uppercase tracking-wider">
                                    {lastSaved ? `Saved: ${lastSaved.toLocaleTimeString()}` : 'Unsaved'}
                                </div>
                                <button onClick={() => { onSave(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50 flex items-center gap-2">💾 Save Project</button>
                                <button onClick={() => { onImport(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm hover:bg-slate-50 flex items-center gap-2">📂 Import JSON</button>
                                <button onClick={() => onExportProject()} className="px-4 py-2 text-left text-sm hover:bg-slate-50 flex items-center gap-2">📦 Export All</button>
                                <button onClick={() => onExportFunction()} className="px-4 py-2 text-left text-sm hover:bg-slate-50 flex items-center gap-2">📄 Export Function</button>
                                <div className="h-px bg-slate-100 my-1"></div>
                                <button onClick={() => { onClear(); setIsProjectMenuOpen(false); }} className="px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2">🗑️ Reset All</button>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Toolbar;

import React, { ReactNode } from 'react';

interface ModalProps {
    isOpen: boolean;
    title: string;
    children: ReactNode;
    onClose: () => void;
    onSubmit: () => void;
}

const Modal: React.FC<ModalProps> = ({ isOpen, title, children, onClose, onSubmit }) => {
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4 animate-fade-in">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden animate-scale-in">
                <div className="bg-slate-50 px-4 py-3 border-b border-slate-100 flex justify-between items-center">
                    <h3 className="font-bold text-slate-700">{title}</h3>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-600">✕</button>
                </div>
                <form onSubmit={(e) => { e.preventDefault(); onSubmit(); }} className="p-4">
                    {children}
                    <div className="flex justify-end space-x-2 mt-4">
                        <button type="button" onClick={onClose} className="px-4 py-2 text-sm font-bold text-slate-500 hover:bg-slate-50 rounded-lg transition-colors">Cancel</button>
                        <button type="submit" className="px-4 py-2 text-sm font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-lg shadow-sm transition-colors">Confirm</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default Modal;

import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; 
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit } from '../types';
import { GRID_SIZE, COLOR_BG } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';
import { CircuitRenderer } from '../logic/circuitRenderer';

declare global {
  interface Window { p5: any; }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
  setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => void;
  focusComponent: (compId: string) => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string, bitWidth?: number } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // Use refs for mutable state accessed by P5 loop
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  const selectedCompId = useRef<string | null>(null);
  const activeDragId = useRef<string | null>(null);

  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);
  const isDraggingComp = useRef<boolean>(false);
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output', bitWidth: number } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 
  const accumulatorRef = useRef<number>(0);

  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Exposed Methods --
  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) Object.assign(comp, updates);
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    },
    setComponentOutputBit: (compId: string, bitIndex: number, value: boolean) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && comp.type === ComponentType.INPUT_SWITCH) {
            const currentBus = comp.outputValues[0] || new Array(comp.bitWidth).fill(false);
            if (currentBus.length !== comp.bitWidth) {
                while(currentBus.length < comp.bitWidth) currentBus.push(false);
            }
            const newBus = [...currentBus];
            newBus[bitIndex] = value;
            comp.outputValues[0] = newBus;
        }
    },
    focusComponent: (compId: string) => {
        const comp = componentsRef.current.find(c => c.id === compId);
        if (comp && containerRef.current) {
             const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
             const w = dims.w * GRID_SIZE;
             const h = dims.h * GRID_SIZE;
             const cx = comp.x + w/2;
             const cy = comp.y + h/2;
             const sw = containerRef.current.clientWidth;
             const sh = containerRef.current.clientHeight;

             viewportRef.current.x = (sw/2) - (cx * viewportRef.current.zoom);
             viewportRef.current.y = (sh/2) - (cy * viewportRef.current.zoom);
        }
    }
  }));

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string, bitWidth: number = 1) => {
    const worldPos = screenToWorld(screenX, screenY);
    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    let inputsCount = 0, outputsCount = 0, label = "", internalState = undefined;
    const def = CircuitRenderer.getComponentDimensions({ type, functionId } as any, libraryRef.current);
    inputsCount = def.inputs;
    outputsCount = def.outputs;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            label = func.name;
            // Deep copy internal state for simulation independence
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill([]), 
      outputValues: new Array(outputsCount).fill([]), 
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined,
      bitWidth: bitWidth
    };

    componentsRef.current.push(newComp);
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId, pendingDrop.bitWidth);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop]);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data && containerRef.current) {
            const parsed = JSON.parse(data);
            const rect = containerRef.current.getBoundingClientRect();
            addComponent(parsed.type, e.clientX - rect.left, e.clientY - rect.top, parsed.functionId, parsed.bitWidth);
        }
    } catch(err) { console.error("Drop failed", err); }
  };

  const getPortWidth = (comp: CircuitComponent, index: number, type: 'input'|'output'): number => {
      // Logic for Splitter/Merger width validation
      if (comp.type === ComponentType.SPLITTER) {
          if (type === 'input') return comp.bitWidth; 
          return comp.bitWidth / 2;
      }
      if (comp.type === ComponentType.MERGER) {
          if (type === 'output') return comp.bitWidth;
          return comp.bitWidth / 2; 
      }
      return comp.bitWidth;
  };

  useEffect(() => {
    if (!containerRef.current || !(window as any).p5) return;
    if (p5InstanceRef.current) p5InstanceRef.current.remove();

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0; let lastTouchY = 0; let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        document.oncontextmenu = () => false; 
      };

      (p as any).windowResized = () => { if(containerRef.current) p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight); };

      p.draw = () => {
        p.background(COLOR_BG);

        // --- Simulation Loop ---
        if (isPlayingRef.current) {
          const speed = tickSpeedRef.current;
          if (speed <= 0) {
              // Max speed: multiple steps per frame
              for(let i=0; i<10; i++) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
              }
              accumulatorRef.current = 0;
          } else {
              accumulatorRef.current += p.deltaTime;
              if (accumulatorRef.current > 500) accumulatorRef.current = 500; // Cap lag
              while (accumulatorRef.current >= speed) {
                const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
                componentsRef.current = result.components;
                wiresRef.current = result.wires;
                accumulatorRef.current -= speed;
              }
          }
        } else accumulatorRef.current = 0;

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        CircuitRenderer.drawGrid(p, viewportRef.current);
        wiresRef.current.forEach(w => CircuitRenderer.drawWire(p, w, componentsRef.current, libraryRef.current));

        if (wiringStart.current) {
             const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
             CircuitRenderer.drawDraftWire(p, wiringStart.current, mouseWorld, componentsRef.current, libraryRef.current);
        }

        componentsRef.current.forEach(comp => {
          CircuitRenderer.drawComponent(p, comp, libraryRef.current, comp.id === selectedCompId.current);
        });

        // --- Hover & Port Highlighting ---
        if (!activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);

            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = CircuitRenderer.getPortPosition(comp, hPort.portIndex, hPort.type, libraryRef.current);

                    // Validate connection capability
                    let isValid = true;
                    if (wiringStart.current) {
                        if (wiringStart.current.compId === comp.id) isValid = false; // No self connect
                        else if (wiringStart.current.type === hPort.type) isValid = false; // Input-Input / Output-Output
                        else if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) isValid = false; // Width Mismatch
                    }

                    p.noFill();
                    p.stroke(isValid ? '#3b82f6' : '#ef4444'); 
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);

                    if (wiringStart.current && !isValid) {
                        p.noStroke(); p.fill('#ef4444'); p.textSize(10);
                        if (wiringStart.current.bitWidth !== getPortWidth(comp, hPort.portIndex, hPort.type)) {
                            p.text(`${getPortWidth(comp, hPort.portIndex, hPort.type)} vs ${wiringStart.current.bitWidth}`, pos.x, pos.y - 15);
                        }
                    }
                }
            }
        }

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number) => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'input', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' as const };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = CircuitRenderer.getPortPosition(comp, i, 'output', libraryRef.current);
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' as const };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number) => {
        for (const comp of componentsRef.current) {
          const dims = CircuitRenderer.getComponentDimensions(comp, libraryRef.current);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- Event Handlers --
      // ... (Touch logic remains mostly same, condensed for brevity but robustness preserved)
      (p as any).touchStarted = (e: any) => { if (e.target !== (p as any).canvas) { isCanvasInteraction = false; return true; } isCanvasInteraction = true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y); } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; lastTouchX = t0.x; lastTouchY = t0.y; p.mousePressed(undefined); } return false; };
      (p as any).touchMoved = (e: any) => { if (!isCanvasInteraction) return true; if (p.touches.length === 2) { const t0 = p.touches[0] as any, t1 = p.touches[1] as any; const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y); if (pinchDistStart > 0) { const scaleFactor = currentDist / pinchDistStart; const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0); const cx = (t0.x + t1.x) / 2, cy = (t0.y + t1.y) / 2; const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom; const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom; viewportRef.current.x = cx - wx * newZoom; viewportRef.current.y = cy - wy * newZoom; viewportRef.current.zoom = newZoom; pinchDistStart = currentDist; } } else if (p.touches.length === 1) { const t0 = p.touches[0] as any; if (activeDragId.current) { isDraggingComp.current = true; const mouseWorld = screenToWorld(t0.x, t0.y); const comp = componentsRef.current.find(c => c.id === activeDragId.current); if (comp) { comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE; comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE; } } else if (isPanningRef.current) { viewportRef.current.x += (t0.x - lastTouchX); viewportRef.current.y += (t0.y - lastTouchY); } lastTouchX = t0.x; lastTouchY = t0.y; } return false; };
      (p as any).touchEnded = () => { if (!isCanvasInteraction) return true; if (p.touches.length === 0) p.mouseReleased(); return false; };

      (p as any).mouseWheel = (e: any) => { 
        if (e.target !== (p as any).canvas) return true;
        const zoomFactor = Math.exp(-e.delta * 0.001); 
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0); 
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom; 
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom; 
        viewportRef.current.zoom = newZoom; 
        viewportRef.current.x = p.mouseX - wx * newZoom; 
        viewportRef.current.y = p.mouseY - wy * newZoom; 
        return false; 
      };

      p.mousePressed = (e: any) => {
        if (e && e.target !== (p as any).canvas) return;
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);

        // Wiring Interaction
        if (port) {
            const comp = componentsRef.current.find(c => c.id === port.compId);
            if (!comp) return;

            // If clicking INPUT port, check if we need to remove existing wire
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    wiresRef.current.splice(existingWireIndex, 1);
                    // Start dragging new wire from the source of the old wire
                    wiringStart.current = { compId: existingWire.fromCompId, portIndex: existingWire.fromPortIndex, type: 'output', bitWidth: existingWire.bitWidth };
                    return;
                }
            }
          wiringStart.current = { ...port, bitWidth: getPortWidth(comp, port.portIndex, port.type) };
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);

        // Component Interaction
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }
          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId;
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }

        // Canvas Pan Interaction
        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return; // Handled by touchMoved
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
        } else if (activeDragId.current) {
           isDraggingComp.current = true;
           const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
           const comp = componentsRef.current.find(c => c.id === activeDragId.current);
           if (comp) {
             comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
             comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
           }
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Click Handling (Not Drag) for Switch Toggle
        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp && comp.type === ComponentType.INPUT_SWITCH) {
              // Only toggle if it's a 1-bit switch for convenience. 
              // Multi-bit switches use the BitViewer.
              if (comp.bitWidth === 1) {
                  const currentVal = comp.outputValues[0] || [];
                  const isAnyOn = currentVal.some(b => b);
                  comp.outputValues[0] = new Array(comp.bitWidth).fill(!isAnyOn);
              }
          }
        }

        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        // Complete Wiring
        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
             const endComp = componentsRef.current.find(c => c.id === endPort.compId);
             const endWidth = endComp ? getPortWidth(endComp, endPort.portIndex, endPort.type) : 0;

             if (endWidth === wiringStart.current.bitWidth) {
                let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
                let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

                // Validate Direction (Output -> Input only)
                if (src.type === 'output' && dst.type === 'input') {
                  // Prevent duplicate wires
                  const exists = wiresRef.current.some(w => w.toCompId === dst.compId && w.toPortIndex === dst.portIndex);
                  if (!exists) {
                    wiresRef.current.push({
                      id: crypto.randomUUID(),
                      fromCompId: src.compId,
                      fromPortIndex: src.portIndex,
                      toCompId: dst.compId,
                      toPortIndex: dst.portIndex,
                      state: new Array(wiringStart.current.bitWidth).fill(false),
                      bitWidth: wiringStart.current.bitWidth
                    });
                  }
                }
             }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new (window as any).p5(sketch, containerRef.current);
    return () => { p5InstanceRef.current?.remove(); };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={(e) => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; }}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;

import React, { useState, useRef, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import LogicCanvas, { LogicCanvasHandle } from './components/LogicCanvas';
import Toolbar from './components/Toolbar';
import Modal from './components/Modal';
import { ComponentType, CircuitComponent } from './types';
import { COMPONENT_DEFINITIONS } from './constants';
import { useProjectManager } from './hooks/useProjectManager';

const App: React.FC = () => {
  // -- UI State --
  const [selectedTool, setSelectedTool] = useState<'SELECT' | 'DELETE'>('SELECT');
  const [isPlaying, setIsPlaying] = useState(false);
  const [speedSlider, setSpeedSlider] = useState(90); 
  const [selectedBitWidth, setSelectedBitWidth] = useState<number>(1);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newFuncName, setNewFuncName] = useState("");

  // -- Component Selection --
  const [selectedComponent, setSelectedComponent] = useState<CircuitComponent | null>(null);
  const [tempLabel, setTempLabel] = useState("");

  // -- Drag & Drop State --
  const [draggedType, setDraggedType] = useState<ComponentType | null>(null);
  const [draggedFuncId, setDraggedFuncId] = useState<string | undefined>(undefined);
  const [dragPos, setDragPos] = useState<{x: number, y: number} | null>(null);
  const [pendingDrop, setPendingDrop] = useState<{type: ComponentType, x: number, y: number, functionId?: string, bitWidth: number} | null>(null);

  // -- Refs --
  const canvasWrapperRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<LogicCanvasHandle>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // -- Hooks --
  const {
      functions,
      activeFunctionId,
      activeFunction,
      lastSaved,
      dataVersion,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  } = useProjectManager(canvasRef);

  // Computed Values
  const tickSpeed = speedSlider === 100 ? 0 : Math.max(1, 500 - (speedSlider * 5));
  const speedLabel = speedSlider === 100 ? "MAX" : `${tickSpeed}ms`;

  // -- Interaction Handlers --

  const handleTouchStartItem = (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => {
    setDraggedType(type);
    setDraggedFuncId(functionId);
    setDragPos(pos);
  };

  useEffect(() => {
    const handleTouchMove = (e: TouchEvent) => {
      if (draggedType) {
        e.preventDefault(); 
        const touch = e.touches[0];
        setDragPos({ x: touch.clientX, y: touch.clientY });
      }
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (draggedType && dragPos && canvasWrapperRef.current) {
        const rect = canvasWrapperRef.current.getBoundingClientRect();
        if (
          dragPos.x >= rect.left && dragPos.x <= rect.right &&
          dragPos.y >= rect.top && dragPos.y <= rect.bottom
        ) {
          setPendingDrop({ type: draggedType, x: dragPos.x - rect.left, y: dragPos.y - rect.top, functionId: draggedFuncId, bitWidth: selectedBitWidth });
        }
      }
      setDraggedType(null);
      setDraggedFuncId(undefined);
      setDragPos(null);
    };

    if (draggedType) {
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', handleTouchEnd);
    }
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [draggedType, draggedFuncId, selectedBitWidth]);

  const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const parsed = JSON.parse(e.target?.result as string);
            if (Array.isArray(parsed)) {
                if (confirm("Replace current project?")) {
                    importData(parsed, true);
                    setSelectedComponent(null);
                    setIsPlaying(false);
                }
            } else if (parsed.id) {
                importData(parsed, false);
                alert(`Imported: ${parsed.name}`);
            }
        } catch (err) { alert("Invalid File"); }
        if (fileInputRef.current) fileInputRef.current.value = "";
    };
    reader.readAsText(file);
  };

  const handleExport = (type: 'PROJECT' | 'FUNCTION') => {
      const data = type === 'PROJECT' 
        ? functions.map(f => f.id === activeFunctionId && canvasRef.current ? {...f, ...canvasRef.current.getData()} : f)
        : (canvasRef.current ? {...activeFunction, ...canvasRef.current.getData()} : activeFunction);

      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = type === 'PROJECT' ? `project.json` : `${activeFunction.name.replace(/\s+/g, '_')}.json`;
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
  };

  const updateProp = (updates: Partial<CircuitComponent>) => {
    if (selectedComponent && canvasRef.current) {
        canvasRef.current.updateSelectedComponent(updates);
        setSelectedComponent(prev => prev ? { ...prev, ...updates } : null);
    }
  };

  const handleSelectionChange = (comp: CircuitComponent | null) => {
      setSelectedComponent(comp);
      setTempLabel(comp?.customLabel || "");
  };

  // Poll for Simulation Updates (Live Monitor)
  const selectedIdRef = useRef<string | null>(null);
  useEffect(() => { selectedIdRef.current = selectedComponent?.id || null; }, [selectedComponent]);

  useEffect(() => {
      if (!isPlaying) return;
      const interval = setInterval(() => {
          const currentId = selectedIdRef.current;
          if (!currentId || !canvasRef.current) return;

          const { components } = canvasRef.current.getData();
          const freshComp = components.find(c => c.id === currentId);

          if (freshComp) {
              setSelectedComponent(prev => {
                  if (!prev || prev.id !== currentId) return prev;
                  // Optimization: Only update React state if logic state changed
                  const prevHash = JSON.stringify({ i: prev.inputValues, o: prev.outputValues });
                  const newHash = JSON.stringify({ i: freshComp.inputValues, o: freshComp.outputValues });
                  return prevHash !== newHash ? { ...freshComp } : prev;
              });
          }
      }, 100);
      return () => clearInterval(interval);
  }, [isPlaying]); 

  return (
    <div className="fixed inset-0 flex bg-slate-50 text-slate-800 font-sans overflow-hidden select-none">
      <input type="file" ref={fileInputRef} onChange={handleFileImport} accept=".json" className="hidden" />

      <Sidebar 
        selectedTool={selectedTool} 
        onSelectTool={setSelectedTool}
        selectedBitWidth={selectedBitWidth}
        onSelectBitWidth={setSelectedBitWidth}
        onTouchStartItem={handleTouchStartItem}
        functionLibrary={functions}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">

        <Toolbar 
            activeFunctionId={activeFunctionId}
            functions={functions}
            isPlaying={isPlaying}
            speedSlider={speedSlider}
            speedLabel={speedLabel}
            selectedComponent={selectedComponent}
            tempLabel={tempLabel}
            lastSaved={lastSaved}
            onTogglePlay={() => setIsPlaying(!isPlaying)}
            onSpeedChange={setSpeedSlider}
            onFunctionChange={(id) => { setIsPlaying(false); switchToFunction(id); }}
            onAddFunction={() => setIsModalOpen(true)}
            onDeleteFunction={deleteFunction}
            onFocusComponent={() => selectedComponent && canvasRef.current?.focusComponent(selectedComponent.id)}
            onUpdateComponent={updateProp}
            onBitToggle={(idx) => {
                if (selectedComponent && canvasRef.current) {
                    const currentBus = selectedComponent.outputValues[0] || new Array(selectedComponent.bitWidth).fill(false);
                    canvasRef.current.setComponentOutputBit(selectedComponent.id, idx, !currentBus[idx]);
                    // Optimistic update
                    const newBus = [...currentBus]; newBus[idx] = !newBus[idx];
                    setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
                }
            }}
            onBatchBusChange={(newBus) => {
                if (selectedComponent && canvasRef.current) {
                    canvasRef.current.updateSelectedComponent({ outputValues: [newBus] });
                    setSelectedComponent({ ...selectedComponent, outputValues: [newBus] });
                }
            }}
            onLabelChange={(val) => { setTempLabel(val); updateProp({ customLabel: val }); }}
            onSave={persist}
            onImport={() => fileInputRef.current?.click()}
            onExportProject={() => handleExport('PROJECT')}
            onExportFunction={() => handleExport('FUNCTION')}
            onClear={() => { if(confirm("Clear all data?")) clearData(); }}
        />

        {/* Main Canvas */}
        <div className="flex-1 w-full h-full relative z-0" ref={canvasWrapperRef}>
          <LogicCanvas 
            key={`${activeFunctionId}-${dataVersion}`}
            ref={canvasRef}
            tool={selectedTool} 
            isPlaying={isPlaying} 
            tickSpeedMs={tickSpeed}
            pendingDrop={pendingDrop}
            initialComponents={activeFunction.components}
            initialWires={activeFunction.wires}
            functionLibrary={functions}
            onPendingDropHandled={() => setPendingDrop(null)}
            onSelectionChange={handleSelectionChange}
          />
        </div>

        {/* Drag Ghost Visual */}
        {draggedType && dragPos && (
          <div className="fixed pointer-events-none z-50 opacity-90" style={{ left: dragPos.x, top: dragPos.y, transform: 'translate(-50%, -50%)' }}>
            <div className="w-12 h-12 bg-white border-2 border-blue-500 rounded-lg flex items-center justify-center shadow-2xl">
              <span className="text-[10px] font-bold text-slate-800">{draggedType === 'IC' ? 'IC' : COMPONENT_DEFINITIONS[draggedType].label.substring(0,3)}</span>
              <span className="absolute -top-2 -right-2 bg-blue-600 text-white text-[9px] w-5 h-5 flex items-center justify-center rounded-full shadow-sm">{selectedBitWidth}</span>
            </div>
          </div>
        )}

        <Modal 
            isOpen={isModalOpen}
            title="Create New Function"
            onClose={() => setIsModalOpen(false)}
            onSubmit={() => {
                if (newFuncName.trim()) {
                    addFunction(newFuncName);
                    setNewFuncName("");
                    setIsModalOpen(false);
                }
            }}
        >
             <input 
                autoFocus 
                type="text" 
                value={newFuncName} 
                onChange={(e) => setNewFuncName(e.target.value)} 
                placeholder="Function Name (e.g., Full Adder)" 
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-200 focus:border-blue-400 outline-none transition-all" 
            />
        </Modal>

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS, VALID_BIT_WIDTHS } from '../constants';
import DraggableItem from './DraggableItem';

interface SidebarProps {
  selectedTool: 'SELECT' | 'DELETE';
  onSelectTool: (t: 'SELECT' | 'DELETE') => void;
  selectedBitWidth: number;
  onSelectBitWidth: (w: number) => void;
  onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
}

const Sidebar: React.FC<SidebarProps> = ({ 
    selectedTool, 
    onSelectTool, 
    selectedBitWidth, 
    onSelectBitWidth,
    onTouchStartItem, 
    functionLibrary 
}) => {
  const [searchTerm, setSearchTerm] = useState("");

  const groups = [
    { name: 'Bus Tools', items: [ComponentType.SPLITTER, ComponentType.MERGER] },
    { name: 'I/O', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.NAND, ComponentType.NOR, ComponentType.XOR] }
  ];

  // Search Logic
  const filteredGroups = groups.map(group => ({
    ...group,
    items: group.items.filter(type => {
        if (!searchTerm) return true;
        const def = COMPONENT_DEFINITIONS[type];
        const lowerTerm = searchTerm.toLowerCase();
        return def.label.toLowerCase().includes(lowerTerm) || 
               def.description.toLowerCase().includes(lowerTerm) ||
               type.toLowerCase().includes(lowerTerm);
    })
  })).filter(g => g.items.length > 0);

  const filteredFunctions = functionLibrary.filter(f => 
      f.id !== 'main' && 
      (searchTerm ? f.name.toLowerCase().includes(searchTerm.toLowerCase()) : true)
  );

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full shadow-lg z-10">
      <div className="p-4 border-b border-slate-100 bg-slate-50/50">
        <h1 className="text-xl font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-xs text-slate-400 mt-1">Bus Width Simulator</p>
      </div>

      <div className="p-3 border-b border-slate-50">
        <div className="relative">
            <span className="absolute left-2.5 top-1.5 text-slate-400 text-sm">🔍</span>
            <input 
                type="text"
                placeholder="Search components..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-8 pr-3 py-1.5 text-sm bg-slate-100 border-transparent focus:bg-white border focus:border-blue-300 rounded-md outline-none transition-all placeholder-slate-400 text-slate-700"
            />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 overscroll-contain scrollbar-thin">

        {/* Tools Section (Always visible) */}
        <section>
          <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">Tools</h3>
          <div className="grid grid-cols-2 gap-2">
            <button
              onClick={() => onSelectTool('SELECT')}
              className={`p-2 rounded text-sm font-medium transition-colors flex items-center justify-center gap-2 ${selectedTool === 'SELECT' ? 'bg-blue-600 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              <span>👆</span> Select
            </button>
            <button
              onClick={() => onSelectTool('DELETE')}
              className={`p-2 rounded text-sm font-medium transition-colors flex items-center justify-center gap-2 ${selectedTool === 'DELETE' ? 'bg-red-500 text-white shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
            >
              <span>🗑️</span> Delete
            </button>
          </div>
        </section>

        {/* Bit Width Section (Always visible) */}
        <section>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2 pl-1">Bus Width (Bits)</h3>
            <div className="flex flex-wrap gap-1.5">
                {VALID_BIT_WIDTHS.map(w => (
                    <button
                        key={w}
                        onClick={() => onSelectBitWidth(w)}
                        className={`px-2.5 py-1 text-xs font-bold rounded border transition-all ${selectedBitWidth === w 
                            ? 'bg-blue-100 border-blue-400 text-blue-700 shadow-sm scale-105' 
                            : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'}`}
                    >
                        {w}
                    </button>
                ))}
            </div>
        </section>

        {/* Component Groups */}
        {filteredGroups.map(group => (
          <section key={group.name}>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">{group.name}</h3>
            <div className="grid grid-cols-2 gap-3">
              {group.items.map(type => {
                const def = COMPONENT_DEFINITIONS[type];
                const disabled = (type === ComponentType.SPLITTER || type === ComponentType.MERGER) && selectedBitWidth < 2;
                const subLabel = type === ComponentType.SPLITTER ? `${selectedBitWidth}→${selectedBitWidth/2}` : 
                                 type === ComponentType.MERGER ? `${selectedBitWidth/2}→${selectedBitWidth}` : 
                                 `x${selectedBitWidth}`;

                return (
                   <DraggableItem 
                        key={type}
                        type={type}
                        label={def.label}
                        subLabel={subLabel}
                        disabled={disabled}
                        bitWidth={selectedBitWidth}
                        onTouchStartItem={onTouchStartItem}
                   />
                );
              })}
            </div>
          </section>
        ))}

        {/* Custom Functions Section */}
        {(filteredFunctions.length > 0 || (searchTerm && filteredFunctions.length === 0)) && (
            <section>
                 <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 pl-1">My Functions</h3>
                 {filteredFunctions.length > 0 ? (
                     <div className="grid grid-cols-1 gap-2">
                        {filteredFunctions.map(func => (
                            <DraggableItem
                                key={func.id}
                                type={ComponentType.CUSTOM_IC}
                                label={func.name}
                                subLabel=""
                                disabled={false}
                                bitWidth={selectedBitWidth}
                                functionId={func.id}
                                isCustom={true}
                                onTouchStartItem={onTouchStartItem}
                            />
                        ))}
                     </div>
                 ) : (
                     <p className="text-xs text-slate-400 italic pl-1">No functions match search.</p>
                 )}
            </section>
        )}

        {filteredGroups.length === 0 && filteredFunctions.length === 0 && searchTerm && (
             <div className="text-center py-8 opacity-50">
                <div className="text-2xl mb-2">🤷‍♂️</div>
                <p className="text-sm">No components found</p>
             </div>
        )}

      </div>
    </div>
  );
};

export default Sidebar;

import React, { useRef } from 'react';
import { ComponentType } from '../types';

interface DraggableItemProps {
    type: ComponentType;
    label: string;
    subLabel: string;
    disabled: boolean;
    bitWidth: number;
    functionId?: string;
    isCustom?: boolean;
    onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
}

const useTouchDrag = (
    disabled: boolean, 
    callback: (pos: {x: number, y: number}) => void
) => {
    const onTouchStart = (e: React.TouchEvent) => {
        if (disabled) return;
        const touch = e.touches[0];
        const pos = { x: touch.clientX, y: touch.clientY };
        // Immediate Drag Start
        callback(pos);
    };

    return {
        onTouchStart,
        onContextMenu: (e: React.MouseEvent) => { if (!disabled) e.preventDefault(); }
    };
};

const DraggableItem: React.FC<DraggableItemProps> = ({ 
    type, label, subLabel, disabled, bitWidth, functionId, isCustom, onTouchStartItem 
}) => {

    const handleDragStart = (e: React.DragEvent) => {
        if (disabled) return;
        e.dataTransfer.setData('application/react-logic-sim', JSON.stringify({ type, functionId, bitWidth }));
        e.dataTransfer.effectAllowed = 'copy';
    };

    const touchHandlers = useTouchDrag(disabled, (pos) => {
        if (onTouchStartItem) onTouchStartItem(type, pos, functionId);
    });

    if (isCustom) {
        return (
             <div
                draggable={!disabled}
                onDragStart={handleDragStart}
                {...touchHandlers}
                className="flex items-center p-2 rounded border border-slate-200 bg-blue-50 hover:border-blue-300 hover:shadow-sm transition-all duration-200 cursor-grab active:cursor-grabbing select-none"
            >
                 <div className="w-6 h-6 mr-3 border border-blue-200 rounded flex items-center justify-center bg-white text-[9px] font-bold text-blue-600 pointer-events-none">
                    IC
                 </div>
                 <span className="text-sm font-medium text-slate-700 pointer-events-none truncate">{label}</span>
            </div>
        );
    }

    return (
        <div
            draggable={!disabled}
            onDragStart={handleDragStart}
            {...touchHandlers}
            className={`flex flex-col items-center justify-center p-3 rounded border-2 transition-all duration-200 select-none
                ${disabled 
                    ? 'opacity-40 bg-slate-50 border-slate-100 cursor-not-allowed' 
                    : 'bg-white border-slate-100 hover:border-slate-300 hover:shadow-sm cursor-grab active:cursor-grabbing'}`}
        >
            <div className="w-8 h-8 mb-2 border border-slate-300 rounded flex items-center justify-center bg-white text-[10px] font-bold text-slate-600 pointer-events-none">
                {label.substring(0,3)}
            </div>
            <span className="text-xs font-medium text-slate-700 pointer-events-none">{label}</span>
            <span className="text-[9px] text-slate-400 font-mono mt-1">{subLabel}</span>
        </div>
    );
};

export default DraggableItem;

